const slug = slugify(projectData.project_title);
const html = buildProjectHtml(projectData);

const projectsJsonEntry = {
  slug,
  title: projectData.project_title,
  excerpt: projectData.short_description,
  image: `/projects/${slug}.jpg`,
  category: projectData.category,
  tags: splitCsv(projectData.tags),
  technologies: splitCsv(projectData.technologies_used),
  date: String(projectData.project_date || '').slice(0, 10),
  clientName: projectData.client_name,
  clientCompany: projectData.client_company,
  duration: projectData.project_duration,
  status: 'Completed',
  featured: true,
  projectLink: `https://alecasgari.com/projects/${slug}.html`,
  url: `/projects/${slug}.html`,
};

return {
  slug,
  project_id: projectData.project_id,
  project_link: `https://alecasgari.com/projects/${slug}.html`,
  image_path: `/projects/${slug}.jpg`,
  base64_html: Buffer.from(html, 'utf8').toString('base64'),
  projects_json_entry: projectsJsonEntry,
};

// دریافت متن خام خروجی از هوش مصنوعی با سینتکس درست n8n
let rawText = $input.first().json.candidates[0].content.parts[0].text;

// پاک‌سازی باک‌تیک‌های مارک‌داون در صورتی که مدل آن‌ها را تولید کرده باشد
if (rawText.includes('```')) {
  rawText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
}

try {
  // ۱. تبدیل متن تمیز شده به یک شیء JSON واقعی
  const parsedData = JSON.parse(rawText);

  // ۲. اضافه کردن یک آیدی ۷ رقمی یکتا به جیسون
  parsedData.project_id = Math.floor(1000000 + Math.random() * 9000000).toString();

  // ۳. بازگرداندن دیتای نهایی که الان آیدی هم توش هست
  return parsedData;

} catch (error) {
  // بازگرداندن خطا در صورت عدم موفقیت
  return { error: "JSON format invalid", message: error.message, raw: rawText };
}

// ۱. دریافت متن پیام از ساختار تلگرام
const messageText = $('Telegram Trigger1').first().json.callback_query.message.text;

// ۲. جداسازی خطوط، حذف فاصله‌های خالی و فیلتر کردن هدر و فوتر پیام
const tagsArray = messageText.split('\n')
  .map(line => line.trim())
  .filter(line => line !== '' && !line.toUpperCase().startsWith('TAGS ARE') && !line.includes('Do you need images'));

// ۳. خروجی دادن به صورت یک آبجکت حاوی آرایه‌ای از تگ‌ها (دقیقاً مشابه تصویر شما)
return {
  tags: tagsArray
};

// اسکن کردن تمام آیتم‌های ورودی
for (const item of $input.all()) {
  // اگر فایل باینری با نام data وجود داشت (که خروجی دیفالت تلگرامه)
  if (item.binary && item.binary.data) {
    // تغییر اجباری لیبل فایل به فرمت صوتی استاندارد تلگرام
    item.binary.data.mimeType = 'audio/ogg';
    item.binary.data.fileExtension = 'ogg';
    item.binary.data.fileName = 'voice_message.ogg';
  }
}

// بازگرداندن دیتای اصلاح‌شده به نود بعدی (جمنای)
return $input.all();

// 1. گرفتن دیتای پروژه از شیت
const projectData = $('Get Project for photo').first().json;

// 2. گرفتن باینری واقعی از n8n (در filesystem هم درست کار می‌کند)
const binaryData = await this.helpers.getBinaryDataBuffer(0, 'data');

// 3. تبدیل به Base64 خام و تمیز
const base64String = binaryData.toString('base64');

// 4. تابع slugify
function slugify(title) {
  return title
    .trim()
    .replace(/[^\w\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .slice(0, 80);
}

// 5. ساخت مسیرها
const slug = slugify(projectData.project_title);
const imagePath = `/projects/${slug}.jpg`;
const projectLink = `https://alecasgari.com/projects/${slug}.html`;

// 6. خروجی نهایی — همه چیز + base64 تمیز
return {
  project_id: projectData.project_id,
  project_title: projectData.project_title,
  slug,
  project_link: projectLink,
  image_path: imagePath,
  base64_image: base64String
};

// n8n Code node — نام پیشنهادی: Merge projects JSON
// ورودی: خروجی node «Get projects.json» (GitHub)
// فقط از Prepare HTML for GitHub برای entry استفاده می‌کند

const entry = $('Prepare HTML for GitHub').first().json.projects_json_entry;

if (!entry || !entry.slug) {
  throw new Error('projects_json_entry not found. Run Prepare HTML for GitHub first.');
}

let existing = [];
const item = $input.first().json;

try {
  if (item.content) {
    const b64 = String(item.content).replace(/\s/g, '');
    existing = JSON.parse(Buffer.from(b64, 'base64').toString('utf8'));
  } else if (typeof item.data === 'string') {
    existing = JSON.parse(item.data);
  }
} catch (e) {
  existing = [];
}

if (!Array.isArray(existing)) existing = [];

const filtered = existing.filter((p) => p.slug !== entry.slug);
filtered.unshift(entry);

const jsonText = JSON.stringify(filtered, null, 2) + '\n';

return {
  slug: entry.slug,
  project_id: $('Prepare HTML for GitHub').first().json.project_id,
  project_link: entry.url ? `https://alecasgari.com${entry.url}` : '',
  base64_projects_json: Buffer.from(jsonText, 'utf8').toString('base64'),
};
